const fs = require('node:fs')
const fsp = fs.promises
const call = (name, ...args) =>
  new Promise((resolve, reject) => {
    fs[name](...args, (err, value) => (err ? reject(err) : resolve(value)))
  })
await fsp.writeFile('/data/f.txt', 'abc')
const fd = await call('open', '/data/f.txt', 'r+')
const buffer = Buffer.alloc(3)
const n = await call('read', fd, buffer, 0, 3, 0)
await call('write', fd, 'XY', 0)
await call('fsync', fd)
console.log(buffer.toString('utf8', 0, n), await call('readFile', fd, 'utf8'))
await call('close', fd)
const h = await fsp.open('/data/s.txt', 'w')
await fsp.rename('/data/s.txt', '/data/streamed.txt')
await new Promise((resolve, reject) => {
  h.createWriteStream().on('error', reject).on('close', resolve).end('streamed')
})
const chunks = []
await new Promise((resolve, reject) => {
  fs.createReadStream('/data/streamed.txt')
    .on('data', (chunk) => chunks.push(chunk))
    .on('error', reject)
    .on('close', resolve)
})
const old = await fsp.access('/data/s.txt').then(() => 'there', () => 'gone')
console.log(Buffer.concat(chunks).toString(), old)
const w = await fsp.open('/data/w.txt', 'w')
await fsp.writeFile(w, 'via handle')
await w.close()
console.log(await fsp.readFile('/data/w.txt', 'utf8'))

